1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export type Step = QuoteStep | ClaimStep;
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	export interface ClaimStep {
21	  op: "claim";
22	  policy: number;
23	  incident: Incident;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type Result = QuoteResult | ClaimResult;
37	
38	export interface QuoteResult {
39	  premium: number;
40	}
41	
42	export interface ClaimResult {
43	  payout: number;
44	  remainingCap: number;
45	}
46	
47	export interface ScenarioResult {
48	  results: Result[];
49	}
50	
51	const PROCESSING_FEE = 5;
52	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
53	const BASE_PREMIUMS: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	};
59	
60	const policyBasePremium = (items: Item[]): number =>
61	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
62	
63	// Premiums round up, in the MHPCO's favour. The surcharge is added as a
64	// separate term rather than folded into a `base * 1.1` factor, which is not
65	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
66	const quotePremium = (items: Item[]): number => {
67	  const base = policyBasePremium(items);
68	  return Math.ceil(base + base * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE);
69	};
70	
71	const quote = (step: QuoteStep): QuoteResult => ({
72	  premium: quotePremium(step.items),
73	});
74	
75	const runStep = (step: Step): Result => {
76	  switch (step.op) {
77	    case "quote":
78	      return quote(step);
79	    default:
80	      throw new Error(`unsupported step: ${step.op}`);
81	  }
82	};
83	
84	export const runScenario = (scenario: Scenario): ScenarioResult => ({
85	  results: scenario.steps.map(runStep),
86	});
87

